/* No framework, no build step, no network beyond this origin.
 *
 * Everything the page needs is in data/manifest.json plus one JSON file per
 * index, all generated by `python3 -m osrs_index publish`. The whole point of
 * exporting plain JSON rather than serving SQLite is that this file can be
 * ~200 lines of fetch-and-render instead of a WASM database driver. */

const fmt = {
  level: (v) => v == null ? "—" : v.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 }),
  pct: (v) => v == null ? "—" : (v >= 0 ? "+" : "") + (v * 100).toFixed(2) + "%",
  gp(v) {
    if (v == null) return "—";
    const abs = Math.abs(v);
    if (abs >= 1e12) return (v / 1e12).toFixed(2) + "T";
    if (abs >= 1e9) return (v / 1e9).toFixed(2) + "B";
    if (abs >= 1e6) return (v / 1e6).toFixed(1) + "M";
    if (abs >= 1e3) return (v / 1e3).toFixed(1) + "K";
    return Math.round(v).toLocaleString("en-US");
  },
  usd: (v) => v == null ? "—" : "$" + Math.round(v).toLocaleString("en-US"),
};

const el = (id) => document.getElementById(id);
const cache = new Map();
let chart = null;
let series = null;
let simSeries = null;
let selected = null;

/* The chart library has no theme awareness, so feed it the resolved values
 * from our own CSS custom properties. Reading them back means the two themes
 * can never drift apart. */
function themeColors() {
  const css = getComputedStyle(document.documentElement);
  const read = (name, fallback) => (css.getPropertyValue(name) || fallback).trim();
  return {
    text: read("--muted", "#8b949e"),
    border: read("--border", "#2a313b"),
    accent: read("--accent", "#58a6ff"),
    bg: read("--panel", "#161b22"),
  };
}

function ensureChart() {
  if (chart) return chart;
  const c = themeColors();
  chart = LightweightCharts.createChart(el("chart"), {
    layout: { background: { color: c.bg }, textColor: c.text, attributionLogo: false },
    grid: { vertLines: { color: c.border }, horzLines: { color: c.border } },
    rightPriceScale: { borderColor: c.border },
    timeScale: { borderColor: c.border, fixLeftEdge: true, fixRightEdge: true },
    crosshair: { mode: LightweightCharts.CrosshairMode.Normal },
    autoSize: true,
  });
  const price = { type: "price", precision: 2, minMove: 0.01 };
  /* Two series, not one. The backtest and the live record must not render as
   * the same line -- splicing them is how a project that means to be honest
   * ends up publishing a performance claim. */
  simSeries = chart.addSeries(LightweightCharts.LineSeries, {
    color: c.text,
    lineWidth: 1,
    lineStyle: LightweightCharts.LineStyle.Dotted,
    priceFormat: price,
    priceLineVisible: false,
  });
  series = chart.addSeries(LightweightCharts.AreaSeries, {
    lineColor: c.accent,
    topColor: c.accent + "44",
    bottomColor: c.accent + "05",
    lineWidth: 2,
    priceFormat: price,
  });
  return chart;
}

async function load(indexId) {
  if (cache.has(indexId)) return cache.get(indexId);
  const res = await fetch(`data/${indexId}.json`, { cache: "no-cache" });
  if (!res.ok) throw new Error(`${indexId}: HTTP ${res.status}`);
  const payload = await res.json();
  cache.set(indexId, payload);
  return payload;
}

function renderCards(manifest) {
  const box = el("cards");
  box.innerHTML = "";
  for (const entry of manifest.indices) {
    const card = document.createElement("button");
    card.className = "card";
    card.type = "button";
    card.setAttribute("role", "tab");
    card.setAttribute("aria-selected", "false");
    card.dataset.id = entry.index_id;

    const dir = entry.change_24h == null ? "" : entry.change_24h >= 0 ? "up" : "down";
    const stale = entry.quality && entry.quality !== "ok"
      ? `<span class="pill">${entry.quality}</span>` : "";

    card.innerHTML =
      `<div class="cname">${entry.name}${stale}</div>` +
      `<div class="clevel">${fmt.level(entry.level)}</div>` +
      `<div class="cmeta ${dir}">${fmt.pct(entry.change_24h)} · ${entry.n_members} members</div>`;

    card.addEventListener("click", () => select(entry.index_id));
    box.appendChild(card);
  }
}

function renderDetail(payload) {
  el("detail").hidden = false;
  el("d-name").textContent = payload.name;
  el("d-desc").textContent = payload.description;
  el("d-level").textContent = fmt.level(payload.level);

  const change = el("d-change");
  change.textContent = fmt.pct(payload.change_24h) + " (24h)";
  change.className = "change " + (payload.change_24h == null ? "" : payload.change_24h >= 0 ? "up" : "down");

  ensureChart();
  const split = payload.split_at ?? payload.series.length;
  /* Overlap by one point so the two lines meet instead of leaving a gap. */
  simSeries.setData(payload.series.slice(0, Math.min(split + 1, payload.series.length)));
  series.setData(payload.series.slice(split));
  chart.timeScale().fitContent();

  const n = payload.series.length;
  const observed = n - split;
  const parts = [`${n} daily observations`];
  if (split > 0) {
    parts.push(
      `the first ${split} are a <strong>backtest</strong> (dotted) reconstructed from stored daily bars — ` +
      `survivorship-biased by today's candidate pool, valued daily rather than hourly, ` +
      `and charged no spread or GE tax`
    );
  }
  parts.push(
    observed > 0
      ? `${observed} observed live (solid) from ${payload.observed_from}`
      : "no live observations yet"
  );
  parts.push(`base level ${payload.base_level} at inception`);
  el("d-serieshint").innerHTML = parts.join(" · ") + ".";

  const body = el("d-constituents").querySelector("tbody");
  body.innerHTML = "";
  for (const c of payload.constituents) {
    const row = document.createElement("tr");
    row.innerHTML =
      `<td>${c.name}${c.capped ? '<span class="pill">capped</span>' : ""}</td>` +
      `<td class="r">${(c.weight * 100).toFixed(2)}%</td>` +
      `<td class="r">${fmt.gp(c.price)}</td>`;
    body.appendChild(row);
  }
  const capped = payload.constituents.filter((c) => c.capped).length;
  el("d-capnote").textContent = capped
    ? `${capped} constituent${capped > 1 ? "s" : ""} hit the liquidity cap: weight limited to 3× share of basket turnover.`
    : "";

  const exBody = el("d-excluded").querySelector("tbody");
  exBody.innerHTML = "";
  if (!payload.excluded.length) {
    exBody.innerHTML = '<tr><td colspan="2" class="muted">Nothing excluded — every candidate made the basket.</td></tr>';
  }
  for (const x of payload.excluded) {
    const why = x.reasons.length
      ? x.reasons.join("; ")
      : "eligible, but outranked at selection";
    const row = document.createElement("tr");
    row.innerHTML = `<td>${x.name}</td><td class="reason">${why}</td>`;
    exBody.appendChild(row);
  }

  const a = payload.attack;
  el("d-attack").innerHTML = a
    ? `<strong>${fmt.gp(a.cost_gp)} gp</strong> (~${fmt.usd(a.cost_usd)}) via <em>${a.item}</em><br>` +
      `needs a ${(a.required_item_move * 100).toFixed(0)}% move on that item across ${a.accounts} account(s)<br>` +
      `profitable above ${fmt.gp(a.breakeven_gp)} gp of exposure` +
      (a.beyond_linear_model
        ? '<br><span class="muted">beyond the linear model — true cost is higher and convex</span>'
        : "")
    : "not computed";

  el("d-capacity").innerHTML = payload.creation_capacity_gp
    ? `<strong>${fmt.gp(payload.creation_capacity_gp)} gp</strong> per account per day`
    : "not computable — at least one member has no published buy limit";
}

async function select(indexId) {
  selected = indexId;
  for (const card of document.querySelectorAll(".card")) {
    card.setAttribute("aria-selected", String(card.dataset.id === indexId));
  }
  try {
    renderDetail(await load(indexId));
  } catch (err) {
    el("detail").hidden = false;
    el("d-name").textContent = "Could not load index";
    el("d-desc").textContent = String(err);
  }
}

async function main() {
  let manifest;
  try {
    const res = await fetch("data/manifest.json", { cache: "no-cache" });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    manifest = await res.json();
  } catch (err) {
    el("cards").innerHTML =
      `<p class="loading">No index data yet (${err}). Run <code>python3 -m osrs_index publish</code>.</p>`;
    return;
  }

  renderCards(manifest);
  el("generated").textContent =
    "Data generated " + new Date(manifest.generated * 1000).toISOString().replace("T", " ").slice(0, 16) + " UTC.";

  if (manifest.indices.length) await select(manifest.indices[0].index_id);

  /* Rebuild the chart on theme flip: the library bakes colours in at creation. */
  const scheme = window.matchMedia("(prefers-color-scheme: dark)");
  scheme.addEventListener("change", () => {
    if (chart) { chart.remove(); chart = null; series = null; }
    if (selected && cache.has(selected)) renderDetail(cache.get(selected));
  });
}

main();
